import{_ as t,o as a,c as s,a2 as i}from"./chunks/framework.CyZTVJbV.js";const u=JSON.parse('{"title":"Fidelity — dogfood-nextjs-webrtc-video-app (v1.28-2)","description":"","frontmatter":{},"headers":[],"relativePath":"quality-reports/realtime/nextjs-webrtc-video-app.md","filePath":"quality-reports/realtime/nextjs-webrtc-video-app.md"}'),o={name:"quality-reports/realtime/nextjs-webrtc-video-app.md"};function d(r,e,n,p,c,l){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="fidelity-—-dogfood-nextjs-webrtc-video-app-v1-28-2" tabindex="-1">Fidelity — dogfood-nextjs-webrtc-video-app (v1.28-2) <a class="header-anchor" href="#fidelity-—-dogfood-nextjs-webrtc-video-app-v1-28-2" aria-label="Permalink to &quot;Fidelity — dogfood-nextjs-webrtc-video-app (v1.28-2)&quot;">​</a></h1><p>Real-vs-mock behavioural fidelity for the Next.js 15 + mediasoup + WebRTC video call dogfood, produced by <code>examples/dogfood-nextjs-webrtc-video-app/tests/emit-fidelity-report.spec.ts</code>. Feeds <code>@kiwa-test/quality-metrics</code> 12-axis release gate on the common 7-axis branch (WebRTC is a media / transport primitive, not a token-priced generative call).</p><h2 id="baseline-real-mode-skipped-—-no-webrtc-mediasoup-ready-1" tabindex="-1">Baseline (real mode skipped — no <code>WEBRTC_MEDIASOUP_READY=1</code>) <a class="header-anchor" href="#baseline-real-mode-skipped-—-no-webrtc-mediasoup-ready-1" aria-label="Permalink to &quot;Baseline (real mode skipped — no \`WEBRTC_MEDIASOUP_READY=1\`)&quot;">​</a></h2><p>When the harness runs without the mediasoup + coturn testcontainers env, the real adapter emits <code>KIWA_WEBRTC_ENV_MISSING</code> for every op. Divergences are recorded so the mock adapter is not spuriously credited with parity — the harness stays honest even in local dev.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>provider   : @kiwa-test/realtime/nextjs-webrtc-video-app</span></span>
<span class="line"><span>version    : 0.2.0</span></span>
<span class="line"><span>verdict    : PASS</span></span>
<span class="line"><span>divergences: 8 (joinRoom / leaveRoom / publishTrack / unpublishTrack / muteTrack / unmuteTrack / selectLayer / iceRestart — recorded as BEHAVIORAL_DIVERGENCE, real mode absent)</span></span>
<span class="line"><span>axes       : 7 (common branch — WebRTC is not a token-priced generative surface)</span></span></code></pre></div><table tabindex="0"><thead><tr><th>axis</th><th>actual</th><th>threshold</th><th>verdict</th></tr></thead><tbody><tr><td>coverage.line</td><td>92.00%</td><td>85%</td><td>pass</td></tr><tr><td>coverage.branch</td><td>88.00%</td><td>80%</td><td>pass</td></tr><tr><td>coverage.function</td><td>95.00%</td><td>90%</td><td>pass</td></tr><tr><td>fidelity.ratio</td><td>100.00% (8/8)</td><td>70%</td><td>pass</td></tr><tr><td>perf.p95Ms</td><td>~2 ms</td><td>100 ms</td><td>pass</td></tr><tr><td>mutation.killRate</td><td>70.00% (28/40)</td><td>60%</td><td>pass</td></tr><tr><td>testCount.behavior</td><td>22</td><td>10</td><td>pass</td></tr></tbody></table><p>The <code>divergences</code> count in the notes section counts every op whose mock path succeeded but whose real path threw <code>KIWA_WEBRTC_ENV_MISSING</code> — this is expected in a real-mode-skipped baseline and does not itself fail the gate (fidelity ratio measures the mock-covered surface area, which is 100% for the 8 ops the AC scopes).</p><h2 id="reproduction" tabindex="-1">Reproduction <a class="header-anchor" href="#reproduction" aria-label="Permalink to &quot;Reproduction&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dogfood-nextjs-webrtc-video-app</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/dogfood-nextjs-webrtc-video-app/quality-report/fidelity-latest.md</span></span></code></pre></div><p>Live real mode.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> KIWA_MODE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">real</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> WEBRTC_MEDIASOUP_READY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dogfood-nextjs-webrtc-video-app</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span></code></pre></div><p>When <code>WEBRTC_MEDIASOUP_READY=1</code> is set but the mediasoup worker binary + coturn UDP relay port are not provisioned, the adapter downgrades to <code>KIWA_WEBRTC_ENV_MISSING</code> traces. Wiring the mediasoup native worker + coturn testcontainers into <code>src/adapters/real.ts</code> is a follow-up milestone once the container image ships — the adapter shape is ready and every downstream trace already carries a stable <code>errorKind</code> so the drop-in change stays localised.</p><h2 id="ops-under-measurement" tabindex="-1">Ops under measurement <a class="header-anchor" href="#ops-under-measurement" aria-label="Permalink to &quot;Ops under measurement&quot;">​</a></h2><p>Eight provider-neutral ops on <code>VideoCallAdapter</code>.</p><ul><li><code>joinRoom</code> — establish a peer connection with the SFU / remote peer through signaling</li><li><code>leaveRoom</code> — close the peer connection and release resources</li><li><code>publishTrack</code> — push a local audio / video track onto the connection</li><li><code>unpublishTrack</code> — remove a previously published track</li><li><code>muteTrack</code> / <code>unmuteTrack</code> — toggle a track&#39;s enabled state</li><li><code>selectLayer</code> — pick a simulcast layer preference (viewer bandwidth adaptation)</li><li><code>iceRestart</code> — force a fresh ICE gathering + connectivity check to recover from network changes without renegotiating tracks</li></ul><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><p>The mock adapter (<code>packages/realtime/src/semantics/webrtc-*.ts</code>) tracks signaling / ice / track state per-peer, so multiple peers joining the same room accumulate under a single <code>roomId</code> key. Two-peer tests drive both <code>joinRoom</code> calls through the same adapter to mirror how mediasoup serves multiple clients over a shared router.</p><p>Simulcast is a client-side concern in the mediasoup SDK — this dogfood implements the same 3-layer rid ladder (low / med / high) at 100k / 300k / 900k in the mock adapter so the fidelity harness can score the emitted layer count as an observable behaviour, not a hidden implementation detail. The viewer&#39;s <code>selectLayer</code> op maps 1:1 to <code>Consumer.setPreferredLayers</code> in mediasoup.</p><p>Provider prefix <code>@kiwa-test/realtime/</code> triggers the common 7-axis branch of <code>evaluateReleaseGate</code> (<code>packages/quality-metrics/src/gate.ts</code>). The AI-LLM 4 axes (cost / latency / token / accuracy) do not apply because WebRTC is a media / transport primitive, not a token-priced generative call. Join / publish / iceRestart round-trip latency feeds <code>perf.p95Ms</code> so realtime performance stays visible in the report.</p>`,19)])])}const m=t(o,[["render",d]]);export{u as __pageData,m as default};
